
if ('serviceWorker' in navigator) {
  // Registrar el Service Worker que hace que la app abra sin internet.
  // Estrategia network-first: con internet trae lo nuevo, sin internet usa la copia.
  window.addEventListener('load', function(){
    navigator.serviceWorker.register('sw.js').then(function(reg){
      window._swActivo = true;
      console.log('✅ Service Worker registrado — la app puede abrir sin internet.');
    }).catch(function(err){
      window._swActivo = false;
      console.log('No se pudo registrar el service worker:', err);
    });
  });
}
